{
  "name": "通用Modbus从站设备",
  "name_en": "Generic Modbus Slave Device",
  "manufacturer": "",
  "description": "支持 Modbus RTU 或 Modbus TCP 通讯的通用现场设备，例如 PLC、远程 I/O 模块、过程控制器、传感器接口或执行器控制单元。此类设备常用于实验室自动化与测试系统中，通过线圈、离散输入和寄存器交换开关量状态、测量值、设定值以及诊断信息。",
  "description_en": "A generic field device that communicates via Modbus RTU or Modbus TCP, such as a PLC, remote I/O module, process controller, sensor interface, or actuator control unit. In laboratory automation and test systems, such devices are commonly used to exchange digital states, measurements, setpoints, and diagnostic information through coils, discrete inputs, and registers.",
  "actions": [
    {
      "action_name": "auto-read_coils",
      "description": "读取设备线圈状态。",
      "description_en": "Read coil states from the device."
    },
    {
      "action_name": "auto-read_discrete_inputs",
      "description": "读取设备离散输入状态。",
      "description_en": "Read discrete input states from the device."
    },
    {
      "action_name": "auto-write_coil",
      "description": "写入单个线圈值。",
      "description_en": "Write a single coil value."
    },
    {
      "action_name": "auto-write_coils",
      "description": "写入多个线圈值。",
      "description_en": "Write multiple coil values."
    },
    {
      "action_name": "auto-write_register",
      "description": "写入单个保持寄存器值。",
      "description_en": "Write a single holding register value."
    },
    {
      "action_name": "auto-write_registers",
      "description": "写入多个保持寄存器值。",
      "description_en": "Write multiple holding register values."
    },
    {
      "action_name": "auto-read_holding_registers",
      "description": "读取保持寄存器值。",
      "description_en": "Read holding register values."
    },
    {
      "action_name": "auto-read_input_registers",
      "description": "读取输入寄存器值。",
      "description_en": "Read input register values."
    },
    {
      "action_name": "auto-readwrite_registers",
      "description": "同时读取保持寄存器并写入保持寄存器。",
      "description_en": "Read holding registers while writing holding registers in one operation."
    },
    {
      "action_name": "auto-mask_write_register",
      "description": "按位掩码修改保持寄存器。",
      "description_en": "Modify a holding register using bit masks."
    },
    {
      "action_name": "auto-read_device_information",
      "description": "读取设备标识和附加信息。",
      "description_en": "Read device identification and additional information."
    },
    {
      "action_name": "auto-report_slave_id",
      "description": "读取从站 ID 信息。",
      "description_en": "Report the slave ID information."
    },
    {
      "action_name": "auto-read_exception_status",
      "description": "读取设备异常状态。",
      "description_en": "Read the device exception status."
    },
    {
      "action_name": "auto-get_com_event_counter",
      "description": "读取通信事件计数器。",
      "description_en": "Read the communication event counter."
    },
    {
      "action_name": "auto-get_com_event_log",
      "description": "读取通信事件日志。",
      "description_en": "Read the communication event log."
    },
    {
      "action_name": "auto-return_query_data",
      "description": "回送查询数据以进行链路诊断。",
      "description_en": "Loop back query data for link diagnostics."
    },
    {
      "action_name": "auto-restart_comm_option",
      "description": "重启设备通信接口并重置相关通信状态。",
      "description_en": "Restart the device communication interface and reset related communication status."
    },
    {
      "action_name": "auto-return_diagnostic_register",
      "description": "读取诊断寄存器。",
      "description_en": "Read the diagnostic register."
    },
    {
      "action_name": "auto-change_ascii_input_delimiter",
      "description": "更改 ASCII 通讯输入分隔符。",
      "description_en": "Change the ASCII communication input delimiter."
    },
    {
      "action_name": "auto-force_listen_only_mode",
      "description": "使设备进入仅监听模式。",
      "description_en": "Force the device into listen-only mode."
    },
    {
      "action_name": "auto-clear_counters",
      "description": "清除计数器和诊断寄存器。",
      "description_en": "Clear counters and diagnostic registers."
    },
    {
      "action_name": "auto-return_bus_message_count",
      "description": "读取总线消息计数。",
      "description_en": "Read the bus message count."
    },
    {
      "action_name": "auto-return_bus_com_error_count",
      "description": "读取总线通信错误计数。",
      "description_en": "Read the bus communication error count."
    },
    {
      "action_name": "auto-return_bus_exception_error_count",
      "description": "读取总线异常错误计数。",
      "description_en": "Read the bus exception error count."
    },
    {
      "action_name": "auto-return_slave_message_count",
      "description": "读取从站消息计数。",
      "description_en": "Read the slave message count."
    },
    {
      "action_name": "auto-return_slave_no_response_count",
      "description": "读取从站无响应计数。",
      "description_en": "Read the slave no-response count."
    },
    {
      "action_name": "auto-return_slave_no_ack_count",
      "description": "读取从站无确认计数。",
      "description_en": "Read the slave no-acknowledge count."
    },
    {
      "action_name": "auto-return_slave_busy_count",
      "description": "读取从站忙碌计数。",
      "description_en": "Read the slave busy count."
    },
    {
      "action_name": "auto-return_slave_bus_char_overrun_count",
      "description": "读取从站总线字符溢出计数。",
      "description_en": "Read the slave bus character overrun count."
    },
    {
      "action_name": "auto-return_iop_overrun_count",
      "description": "读取 IOP 溢出错误计数。",
      "description_en": "Read the IOP overrun error count."
    },
    {
      "action_name": "auto-clear_overrun_count",
      "description": "清除溢出计数。",
      "description_en": "Clear the overrun count."
    },
    {
      "action_name": "auto-get_clear_modbus_plus",
      "description": "读取或清除 Modbus Plus 统计信息。",
      "description_en": "Get or clear Modbus Plus statistics."
    }
  ],
  "tag_hints": [
    "Modbus RTU",
    "Modbus TCP",
    "industrial automation",
    "PLC communication",
    "remote I/O",
    "register I/O",
    "device diagnostics"
  ]
}

